begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('b1190000-0000-4000-8000-000000000001','billing-a@example.invalid'),('b1190000-0000-4000-8000-000000000002','billing-b@example.invalid');
select ok((select relrowsecurity from pg_class where oid='public.billing_events'::regclass),'Billing receipt RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_accounts'::regclass),'Billing account RLS');
set local role anon;
select throws_ok('select * from billing_events','42501',null,'Guest cannot read receipts');
select throws_ok('select * from billing_accounts','42501',null,'Guest cannot read leases');
select throws_ok($$select billing_claim('b1190000-0000-4000-8000-000000000001',false)$$,'42501',null,'Guest cannot claim');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b1190000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok('select * from billing_events','42501',null,'Account cannot read receipts');
select throws_ok('select * from billing_accounts','42501',null,'Account cannot read leases');
select throws_ok($$select billing_commit('b1190000-0000-4000-8000-000000000002',gen_random_uuid(),1,'[]')$$,'42501',null,'Account cannot forge grants');
select throws_ok($$select billing_receive('{"event":{"id":"forged"}}')$$,'42501',null,'Account cannot submit receipts');
reset role;
select is(billing_claim('b1190000-0000-4000-8000-000000000099',false)->>'state','missing','Deleted or unknown account is ignored');
select is(billing_receive('{"event":{"id":"billing-sql-test","type":"RENEWAL"}}')->>'state','pending','Receipt stored');
select is(billing_receive('{"event":{"id":"billing-sql-test","type":"RENEWAL"}}')->>'state','pending','Retry receipt pending');
select is((select count(*)::integer from billing_events where event_id='billing-sql-test'),1,'Unique receipt');
select is(billing_receive('{"event":{"id":"billing-sql-test","type":"EXPIRATION"}}')->>'state','conflict','Collision rejected');
update billing_events set processed_at=now(),outcome='processed' where event_id='billing-sql-test';
select is(billing_receive('{"event":{"id":"billing-sql-test","type":"RENEWAL"}}')->>'state','done','Processed repeat acknowledged');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',false)->>'state','claimed','Lease acquired');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',false)->>'state','busy','Concurrent snapshot excluded');
select ok(not billing_commit('b1190000-0000-4000-8000-000000000001',gen_random_uuid(),1,'[]'),'Other lease cannot commit');
select ok(not billing_commit('b1190000-0000-4000-8000-000000000001',null,1,'[]'),'Missing token cannot commit');
select ok(billing_commit('b1190000-0000-4000-8000-000000000001',(select lease from billing_accounts where user_id='b1190000-0000-4000-8000-000000000001'),2,jsonb_build_array(jsonb_build_object('entitlement','premium','active',true,'expires_at',now()+interval '1 day','store','ios','product_id','monthly','will_renew',true,'billing_issue',false))),'Valid server projection');
select is((tutor_account_status('b1190000-0000-4000-8000-000000000001')->>'tier'),'premium','Tutor grants Premium');
select ok(not billing_commit('b1190000-0000-4000-8000-000000000001',null,3,'[]'),'No lease cannot commit');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',true)->>'state','recent','Manual resync throttled');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',false)->>'state','claimed','Webhook bypasses manual throttle');
select throws_ok($$select billing_commit('b1190000-0000-4000-8000-000000000001',(select lease from billing_accounts where user_id='b1190000-0000-4000-8000-000000000001'),1,'[]')$$,'P0001','Stale billing snapshot','Older snapshot rejected');
select ok((select active from entitlements where user_id='b1190000-0000-4000-8000-000000000001'),'Failed snapshot preserves access');
select ok(billing_commit('b1190000-0000-4000-8000-000000000001',(select lease from billing_accounts where user_id='b1190000-0000-4000-8000-000000000001'),3,'[]'),'Empty verified snapshot revokes');
select is(tutor_account_status('b1190000-0000-4000-8000-000000000001')->>'tier','free','Tutor revokes missing grant');
insert into entitlements(user_id,entitlement,active,expires_at,store) values('b1190000-0000-4000-8000-000000000002','max',true,now()+interval '1 day','manual');
select is(billing_claim('b1190000-0000-4000-8000-000000000002',false)->>'state','claimed','Second account lease');
select ok(billing_commit('b1190000-0000-4000-8000-000000000002',(select lease from billing_accounts where user_id='b1190000-0000-4000-8000-000000000002'),4,'[]'),'Empty snapshot accepted for second account');
select is(tutor_account_status('b1190000-0000-4000-8000-000000000002')->>'tier','max','Explicit manual admin grant preserved');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',false)->>'state','claimed','Lease reacquired');
update billing_accounts set lease_until=now()-interval '1 second' where user_id='b1190000-0000-4000-8000-000000000001';
select ok(not billing_commit('b1190000-0000-4000-8000-000000000001',(select lease from billing_accounts where user_id='b1190000-0000-4000-8000-000000000001'),5,'[]'),'Expired lease rejected');
select is(billing_claim('b1190000-0000-4000-8000-000000000001',false)->>'state','claimed','Expired lease recovers');
set local role authenticated;
select is((select count(*)::integer from entitlements),1,'Only own entitlement visible');
select throws_ok($$update entitlements set active=true$$,'42501',null,'No direct client activation');
reset role;
delete from auth.users where id='b1190000-0000-4000-8000-000000000001';
select is((select count(*)::integer from billing_accounts where user_id='b1190000-0000-4000-8000-000000000001'),0,'Account deletion clears lease');
select * from finish();
rollback;
